/**
 * The x402 rail (letters M4 A and M5 A): the local wallet signs the quote the server returned, under the cap per
 * call (0.05 by default) and the session cap (0.50 by default); above, an explicit refusal with the quoted price
 * and the variable to raise. The receipt the server attaches reaches the client. Nothing is ever replayed.
 * Wallet: a throwaway key generated by the test (no funds); the quotes are the ones recorded on 2026-10-08.
 */
import { decodePaymentSignatureHeader } from "@x402/core/http";
import { generatePrivateKey, privateKeyToAccount } from "viem/accounts";
import { afterEach, describe, expect, it } from "vitest";
import type { CallToolResult } from "@modelcontextprotocol/sdk/types.js";
import { QUOTES, REMOTE, dataResult, serverError } from "./helpers/fixtures.js";
import type { CallAnswer } from "./helpers/fake-remote.js";
import { localServer } from "./helpers/local.js";

const KEY = generatePrivateKey();
const PAYER = privateKeyToAccount(KEY).address;
const RECEIPT = { success: true, transaction: `0x${"ab".repeat(32)}`, network: "eip155:8453", payer: PAYER };

let close: (() => Promise<void>) | undefined;
afterEach(async () => {
  await close?.();
  close = undefined;
});

/** The server: a quote without payment, then `paid` with one. */
function server(quote: CallToolResult, paid: (n: number) => CallAnswer) {
  let n = 0;
  return {
    tools: REMOTE.tools,
    onCall: (_name: string, args: Record<string, unknown>): CallAnswer => (args.x_payment ? paid(++n) : { result: quote }),
  };
}

function errorOf(r: unknown): Record<string, string> {
  return (r as { structuredContent: { resultat: Record<string, string> } }).structuredContent.resultat;
}

describe("x402 rail", () => {
  it("a $0.002 quote is signed locally, the call is replayed once with x_payment, and the server's receipt reaches the client", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, server(QUOTES.search_french_companies, () => ({ result: dataResult(undefined, { "x402/payment-response": RECEIPT }) })));
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(r.isError).toBe(false);
    expect(r._meta?.["x402/payment-response"]).toEqual(RECEIPT);
    const calls = t.remote.calls();
    expect(calls.length).toBe(2);
    expect(calls[0]?.body?.params?.arguments).toEqual({ q: "danone" });
    const header = calls[1]?.body?.params?.arguments?.x_payment as string;
    const payload = decodePaymentSignatureHeader(header);
    expect(payload.accepted.amount).toBe("2000");
    expect(payload.accepted.asset).toBe("0x833589fCD6eDb6E08f4c7C32D4f71b54bdA02913"); // USDC: EURC needs an explicit opt-in
    expect((payload.payload as { authorization: { from: string } }).authorization.from).toBe(PAYER);
    expect(t.local.spent).toBe(2000n);
    // the anonymous endpoint, never a key
    expect(calls.every((c) => c.url === "https://api.sirenic.eu/mcp" && !("authorization" in c.headers))).toBe(true);
    expect(calls.every((c) => c.headers["user-agent"]?.startsWith("sirenic-mcp-npm/"))).toBe(true);
  });

  it("the receipt is the server's only: a paid call whose server attaches none returns none, nor does a refusal by the cap", async () => {
    const t = await localServer(
      { SIRENIC_WALLET_KEY: KEY },
      {
        tools: REMOTE.tools,
        onCall: (name, args): CallAnswer =>
          args.x_payment ? { result: dataResult() } : { result: name === "search_french_companies" ? QUOTES.search_french_companies : QUOTES.get_french_company_default_risk },
      },
    );
    close = t.close;
    const paid = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(paid.isError).toBe(false);
    expect(t.local.spent).toBe(2000n);
    expect(paid._meta?.["x402/payment-response"]).toBeUndefined();
    const capped = await t.client.callTool({ name: "get_french_company_default_risk", arguments: { siren: "552032534" } });
    expect(errorOf(capped).error).toBe("plafond_depasse");
    expect(capped._meta?.["x402/payment-response"]).toBeUndefined();
  });

  it("a $0.10 quote is above the $0.05 cap per call: plafond_depasse with the price and the variable, nothing signed", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, server(QUOTES.get_french_company_default_risk, () => ({ result: dataResult() })));
    close = t.close;
    const r = await t.client.callTool({ name: "get_french_company_default_risk", arguments: { siren: "552032534" } });
    expect(r.isError).toBe(true);
    expect(errorOf(r)).toMatchObject({ error: "plafond_depasse", price_usd: "$0.10", cap_usd: "$0.05", variable: "SIRENIC_MAX_PAR_APPEL" });
    expect(errorOf(r).message).toContain("SIRENIC_MAX_PER_CALL");
    expect(t.remote.calls().length).toBe(1);
    expect(t.local.spent).toBe(0n);
  });

  it("raising SIRENIC_MAX_PAR_APPEL (or its alias) lets the same quote through", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY, SIRENIC_MAX_PER_CALL: "0.10" }, server(QUOTES.get_french_company_default_risk, () => ({ result: dataResult() })));
    close = t.close;
    const r = await t.client.callTool({ name: "get_french_company_default_risk", arguments: { siren: "552032534" } });
    expect(r.isError).toBe(false);
    expect(t.local.spent).toBe(100000n);
  });

  it("the session cap: three $0.002 calls under a $0.005 session cap, the third is refused with SIRENIC_MAX_PAR_SESSION", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY, SIRENIC_MAX_PAR_SESSION: "0.005" }, server(QUOTES.search_french_companies, () => ({ result: dataResult() })));
    close = t.close;
    for (let i = 0; i < 2; i++) expect((await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } })).isError).toBe(false);
    const third = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(errorOf(third)).toMatchObject({ error: "plafond_depasse", price_usd: "$0.002", cap_usd: "$0.005", session_spent_usd: "$0.004", variable: "SIRENIC_MAX_PAR_SESSION" });
    expect(t.local.spent).toBe(4000n);
    expect(t.remote.calls().filter((c) => c.body?.params?.arguments?.x_payment).length).toBe(2);
  });

  it("five calls at once, $0.002 each, under a $0.005 session cap: the cap is reserved before signing, two are signed, never more than the cap", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY, SIRENIC_MAX_PAR_SESSION: "0.005" }, server(QUOTES.search_french_companies, () => ({ result: dataResult() })));
    close = t.close;
    const results = await Promise.all(Array.from({ length: 5 }, () => t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } })));
    const signed = t.remote.calls().filter((c) => c.body?.params?.arguments?.x_payment);
    // floor(0.005 / 0.002) = 2: at most two payments fit under the session cap, whatever the order of the answers
    expect(signed.length).toBe(2);
    expect(t.local.spent).toBe(4000n);
    expect(t.local.spent <= 5000n).toBe(true);
    const refused = results.filter((r) => r.isError).map((r) => errorOf(r));
    expect(refused.length).toBe(3);
    for (const e of refused) expect(e).toMatchObject({ error: "plafond_depasse", cap_usd: "$0.005", variable: "SIRENIC_MAX_PAR_SESSION" });
  });

  it("five calls at once, $0.002 each, under a $0.003 session cap: a single one is signed", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY, SIRENIC_MAX_PAR_SESSION: "0.003" }, server(QUOTES.search_french_companies, () => ({ result: dataResult() })));
    close = t.close;
    const results = await Promise.all(Array.from({ length: 5 }, () => t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } })));
    expect(t.remote.calls().filter((c) => c.body?.params?.arguments?.x_payment).length).toBe(1);
    expect(t.local.spent).toBe(2000n);
    expect(results.filter((r) => !r.isError).length).toBe(1);
  });

  it("a reservation is given back when the payment does not go through (server error, new quote, 429): the next call is signed", async () => {
    // a $0.002 session cap: room for exactly one payment, so a reservation kept by mistake refuses the next call
    const answers: CallAnswer[] = [
      { result: serverError(503, { error: "amont_indisponible", message: "Upstream register unavailable" }) },
      { result: QUOTES.search_french_companies },
      { status: 429 },
      { result: dataResult() },
    ];
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY, SIRENIC_MAX_PAR_SESSION: "0.002" }, server(QUOTES.search_french_companies, (n) => answers[n - 1]!));
    close = t.close;
    const call = () => t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(errorOf(await call()).statut_http).toBe(503);
    expect(errorOf(await call()).error).toBe("paiement_refuse");
    expect(errorOf(await call()).error).toBe("trop_de_requetes");
    expect((await call()).isError).toBe(false);
    expect(t.local.spent).toBe(2000n);
    expect(t.remote.calls().filter((c) => c.body?.params?.arguments?.x_payment).length).toBe(4);
  });

  it("a new quote after the payment: paiement_refuse, nothing replayed, nothing counted", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, server(QUOTES.search_french_companies, () => ({ result: QUOTES.search_french_companies })));
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(errorOf(r).error).toBe("paiement_refuse");
    expect(t.remote.calls().length).toBe(2);
    expect(t.local.spent).toBe(0n);
  });

  it("the connection breaks after the signed payment: reglement_incertain, counted against the session, never replayed", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, server(QUOTES.search_french_companies, () => ({ networkError: "socket hang up" })));
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(errorOf(r).error).toBe("reglement_incertain");
    expect(t.remote.calls().length).toBe(2);
    expect(t.local.spent).toBe(2000n);
  });

  it("a named 503 of the server after the payment reaches the client unchanged, and is not counted (an error cancels the payment)", async () => {
    const error = serverError(503, { error: "amont_indisponible", message: "Upstream register unavailable" });
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, server(QUOTES.search_french_companies, () => ({ result: error })));
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(r.structuredContent).toEqual(error.structuredContent);
    expect(r.isError).toBe(true);
    expect(t.local.spent).toBe(0n);
  });

  it("429 before the tool (rate limit of the MCP endpoint): trop_de_requetes, nothing counted", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, server(QUOTES.search_french_companies, () => ({ status: 429 })));
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(errorOf(r).error).toBe("trop_de_requetes");
    expect(t.local.spent).toBe(0n);
  });

  it("server unreachable for the first call: service_injoignable, nothing signed", async () => {
    const t = await localServer({ SIRENIC_WALLET_KEY: KEY }, { tools: REMOTE.tools, onCall: () => ({ networkError: "ECONNRESET" }) });
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(errorOf(r).error).toBe("service_injoignable");
    expect(t.remote.calls().length).toBe(1);
    expect(t.local.spent).toBe(0n);
  });
});

describe("no rail", () => {
  it("a quote comes back as paiement_requis: the quote, the free key offer, and how to pay; isError false, schema kept", async () => {
    const t = await localServer({}, { tools: REMOTE.tools, onCall: () => ({ result: QUOTES.search_french_companies }) });
    close = t.close;
    // the in-memory client validates structured content against the tool's output schema: a mismatch would throw here
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect(r.isError).toBe(false);
    const s = r.structuredContent as { payment_required: boolean; hint: string; quote: { accepts: unknown[] }; free_tier: { signup_url: string } };
    expect(s.payment_required).toBe(true);
    expect(s.quote.accepts.length).toBe(2);
    expect(s.free_tier.signup_url).toContain("/compte?utm_source=402");
    expect(s.hint).toContain("paiement_requis: this tool costs $0.002 per call.");
    expect(s.hint).toContain("SIRENIC_API_KEY");
    expect(s.hint).toContain("SIRENIC_WALLET_KEY");
    expect(t.remote.calls().length).toBe(1);
  });

  it("paiement_requis carries no receipt: nothing was paid", async () => {
    const t = await localServer({}, { tools: REMOTE.tools, onCall: () => ({ result: QUOTES.search_french_companies }) });
    close = t.close;
    const r = await t.client.callTool({ name: "search_french_companies", arguments: { q: "danone" } });
    expect((r.structuredContent as { payment_required: boolean }).payment_required).toBe(true);
    expect(r._meta?.["x402/payment-response"]).toBeUndefined();
  });

  it("a free tool answers as the server sends it", async () => {
    const t = await localServer({}, { tools: REMOTE.tools, onCall: () => ({ result: dataResult({ suggestions: [] }) }) });
    close = t.close;
    const r = await t.client.callTool({ name: "suggest_company_names", arguments: { q: "dano" } });
    expect(r).toMatchObject(dataResult({ suggestions: [] }));
  });
});
